import React, { useEffect, useRef } from "react";

export default function BouncyPeriod({ exclamation = false, onComplete }) {
  const period = useRef(null);

  useEffect(() => {
    const dot = period.current;
    let disposed = false;
    let media;
    let completed = false;
    const finish = () => {
      if (disposed || completed) return;
      completed = true;
      onComplete?.();
    };

    // Keep the punctuation visible during SSR and if the animation cannot load.
    import("gsap")
      .then(({ gsap }) => {
        if (disposed) return;

        media = gsap.matchMedia();
        media.add({
          motion: "(prefers-reduced-motion: no-preference)",
          reduced: "(prefers-reduced-motion: reduce)",
        }, (context) => {
          if (context.conditions.reduced) {
            finish();
            return;
          }
          const height = parseFloat(window.getComputedStyle(dot).fontSize) * 0.65;
          const glyphs = exclamation
            ? [dot.querySelector(".exclamation-dot"), dot.querySelector(".exclamation-stem")]
            : [dot];
          const timeline = gsap.timeline({ delay: 0.35, onComplete: finish });
          if (exclamation) gsap.set(glyphs, { autoAlpha: 0 });

          glyphs.forEach((glyph, index) => {
            const bounce = gsap.timeline();
            bounce.fromTo(glyph,
              { y: -height, scaleX: 0.9, scaleY: 1.15, autoAlpha: 1 },
              { y: 0, scaleX: 1, scaleY: 1, autoAlpha: 1, duration: 0.28,
                ease: "power2.in", immediateRender: false })
              .to(glyph, { scaleX: 1.45, scaleY: 0.65, duration: 0.07 })
              .to(glyph, { y: -height * 0.45, scaleX: 0.9, scaleY: 1.1, duration: 0.2, ease: "power2.out" })
              .to(glyph, { y: 0, scaleX: 1, scaleY: 1, duration: 0.17, ease: "power2.in" })
              .to(glyph, { scaleX: 1.2, scaleY: 0.8, duration: 0.06 })
              .to(glyph, { y: -height * 0.15, scaleX: 0.95, scaleY: 1.05, duration: 0.13, ease: "power2.out" })
              .to(glyph, { y: 0, scaleX: 1, scaleY: 1, duration: 0.1, ease: "power2.in" })
              .set(glyph, { clearProps: "transform,opacity,visibility" });
            // Drop the stem shortly after the dot starts, during its bounce.
            timeline.add(bounce, index * 0.12);
          });
        });
      })
      .catch(() => {
        // The static punctuation remains readable if the optional chunk fails.
        finish();
      });

    return () => {
      disposed = true;
      media?.revert();
    };
  }, [exclamation, onComplete]);

  return (
    <span ref={period} className={`hero-period${exclamation ? " hero-exclamation" : ""}`}>
      {exclamation ? (
        <>
          <span className="exclamation-stem" aria-hidden="true" />
          <span className="exclamation-dot" aria-hidden="true" />
          <span className="sr-only">!</span>
        </>
      ) : "."}
    </span>
  );
}
